#include <bits/stdc++.h>
using namespace std;

int main() {
	int tt; cin >> tt; 
	while(tt--){
	    int n; cin >> n; //numerb of fields
	    int m; cin >> m; //clouds
	    vector<pair<int,int>>v(n+1);
	    
	    for(int i=1;i<n+1;i++){
	        v[i].first=i;
	        v[i].second=-1;
	    }
	    int max_num=-1, min_num=INT_MAX;
	    
	    for(int i=1;i<m+1;i++){
	        int x;
	        cin>>x;
	        max_num=max(x,max_num);
	        min_num=min(min_num,x);
	        v[i].second=x;
	    }
	    vector<int>temp;
	    for(auto it:v){
	        if(it.second!=-1){
	            temp.push_back(it.first);
	        }
	    }
	    int f=0;
	    int r=n-max_num;
	    int l=min_num-1;
	    //cout << temp.size();
	    for(int i=1;i< (int)temp.size();i++){
	        int diff=abs((temp[i]-temp[i-1])-1);
	        f=max(diff,f);

	    }
	    int ans=0;
	    if(n==m){
	        cout<<0<<endl;
	    }else{
	        //cout <<"l,r: " <<  l << r << endl;
	        //cout << "f" << f << endl;
	        ans=min(2*r+l,2*l+r);
	        //cout << "UP" << ans << endl;
	        ans+=min(0,f-(r+l));
	        cout<<ans<<endl;
	    }
	    
	}
}
